test('vatSummary calculates base and vat correctly', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  // base = 10 * 9500 = 95000
  // vat = 95000 * 21 / 100 = 19950
  assert.equal(result[0].base, 95000);
  assert.equal(result[0].vat, 19950);
});

test('vatSummary aggregates multiple lines with same VAT rate', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // line 1: 95000, line 2: 120000, total base = 215000
  // vat = 95000 * 0.21 + 120000 * 0.21 = 19950 + 25200 = 45150
  assert.equal(result[0].base, 215000);
  assert.equal(result[0].vat, 45150);
});

test('vatSummary separates multiple VAT rates', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 3);
  const rates = result.map((r) => r.rate);
  assert(rates.includes(21));
  assert(rates.includes(9));
  assert(rates.includes(0));
});

