  assert.equal(result[0].vat, 29925);
});

test('vatSummary with mixed statuses', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  let inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(inv2.ok, true);
  let invoice2 = issueInvoice(inv2.value, ['INV-2026-0001']).value;
  invoice2 = recordPayment(invoice2, { amount: 57475, date: '2026-10-08' }).value;

  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'PRINT-A4', qty: 100 }],
  });
  assert.equal(inv3.ok, true);

  const result = vatSummary([issued1.value, invoice2, inv3.value]);
  assert.equal(result.length, 2);
  // issued1 (21%): 95000, vat 19950
  // partially_paid inv2 (21%): 47500, vat 9975
  // draft inv3: excluded
  // total 21%: 142500, vat 29925
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 142500);
  assert.equal(result[0].vat, 29925);
});

